const API_URL="https://app-70zj.onrender.com";const cpfAdm=localStorage.getItem("cpfAdm")?.replace(/\D/g,"");window.addEventListener("load",async()=>{const cpf=localStorage.getItem("cpf")?.replace(/\D/g,"");if(cpf!==cpfAdm){alert("Acesso negado.");window.location.href="../view/index.html";return}try{const res=await fetch(`${API_URL}/usuarios/${cpfAdm}`);if(!res.ok)throw new Error(`Erro HTTP: ${res.status}`);const dadosAdm=await res.json();const config=dadosAdm.configBoletos||null;console.log("Configuração atual de boletos:",config);await configurarBoletos();await gerarCobrancasPixAutomaticas();await carregarUsuarios();await iniciarTutorialAdm()}catch(err){console.error("Erro ao buscar configurações do adm:",err);console.warn("Verifique se o servidor está rodando e a rota está correta.")}});async function carregarUsuarios(){const container=document.getElementById("usuarios-boletos");if(!container)return;container.innerHTML="";try{const res=await fetch(`${API_URL}/usuarios`);if(!res.ok)throw new Error(`Erro HTTP: ${res.status}`);const usuarios=await res.json();usuarios.filter(u=>u.cpf&&u.cpf!==cpfAdm).forEach(usuario=>{const div=document.createElement("div");div.className="usuario";div.innerHTML=`\n          <h3>CPF: ${usuario.cpf}</h3>\n          <p>\n            <button onclick="adicionarCobrancaPix('${usuario.cpf}')">\n              <i class="fas fa-money-check-alt"></i> Cobr. Pix\n            </button>\n            <button onclick="excluirUsuario('${usuario.cpf}')">\n              <i class="fas fa-user-slash"></i> Excluir Usuário\n            </button>\n          </p>\n        `;if(usuario.cobrancas?.length){usuario.cobrancas.forEach((cobranca,i)=>{const c=document.createElement("div");c.className="boleto";c.innerHTML=`\n              <div class="boleto-info">\n                <strong>${cobranca.descricao}</strong><br>\n                Vencimento: ${cobranca.vencimento} | Valor: R$ ${cobranca.valor}\n                <br>\n                <span><strong>Pix:</strong> ${cobranca.chavePix}</span><br>\n                <button onclick="copiarPix('${cobranca.chavePix}')">Copiar chave Pix</button>\n              </div>\n              <div class="boleto-acoes">\n                <button onclick="editarCobrancaPix('${usuario.cpf}', ${i})" title="Editar">\n                  <i class="fas fa-edit"></i>\n                </button>\n                <button onclick="marcarCobrancaComoPaga('${usuario.cpf}', ${i})" title="Marcar como paga">\n                  <i class="fas fa-check-circle"></i>\n                </button>\n                <button onclick="excluirCobranca('${usuario.cpf}', ${i})" title="Excluir cobrança">\n                  <i class="fas fa-trash-alt"></i>\n                </button>\n              </div>\n            `;div.appendChild(c)})}else{div.innerHTML+=`<p><em>Sem cobranças Pix.</em></p>`}container.appendChild(div)})}catch(err){console.error("Erro ao carregar usuários:",err)}}async function adicionarCobrancaPix(cpf){const descricao=prompt("Descrição da cobrança:");const vencimento=prompt("Vencimento (dd/mm/aaaa):");const valor=prompt("Valor:");const chavePix="79683428215";if(!descricao||!vencimento||!valor)return;try{const res=await fetch(`${API_URL}/usuarios/${cpf}/cobrancas`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({descricao:descricao,vencimento:vencimento,valor:valor,chavePix:chavePix})});if(!res.ok)throw new Error(`Erro HTTP: ${res.status}`);await carregarUsuarios()}catch(err){console.error("Erro ao adicionar cobrança Pix:",err)}}async function excluirCobranca(cpf,index){if(!confirm("Excluir cobrança Pix?"))return;try{const res=await fetch(`${API_URL}/usuarios/${cpf}/cobrancas/${index}`,{method:"DELETE"});if(!res.ok)throw new Error(`Erro HTTP: ${res.status}`);await carregarUsuarios()}catch(err){console.error("Erro ao excluir cobrança:",err)}}async function marcarCobrancaComoPaga(cpf,index){try{const res=await fetch(`${API_URL}/usuarios/${cpf}/cobrancas/${index}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({pago:true})});if(!res.ok)throw new Error(`Erro HTTP: ${res.status}`);await carregarUsuarios()}catch(err){console.error("Erro ao marcar cobrança como paga:",err)}}async function editarCobrancaPix(cpf,index){const descricao=prompt("Nova descrição:");const vencimento=prompt("Novo vencimento (dd/mm/aaaa):");const valor=prompt("Novo valor:");if(!descricao||!vencimento||!valor)return;try{const res=await fetch(`${API_URL}/usuarios/${cpf}/cobrancas/${index}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({descricao:descricao,vencimento:vencimento,valor:valor})});if(!res.ok)throw new Error(`Erro HTTP: ${res.status}`);await carregarUsuarios()}catch(err){console.error("Erro ao editar cobrança Pix:",err)}}function copiarPix(chave){navigator.clipboard.writeText(chave).then(()=>alert("Chave Pix copiada!")).catch(()=>alert("Erro ao copiar chave Pix."))}async function iniciarTutorialAdm(){}async function configurarBoletos(){}async function gerarCobrancasPixAutomaticas(){}